#!/usr/bin/env bash
# Reject commit messages that do not follow Conventional Commits.
#
# release-please derives semantic versions and the changelog from commit types,
# so a malformed subject silently breaks the release pipeline instead of failing
# anything visible.
#
# Usage: check_commit_msg.sh <commit-msg-file>   (called by pre-commit)
set -euo pipefail

commit_msg_file="${1:?usage: check_commit_msg.sh <commit-msg-file>}"
subject="$(head -n 1 "$commit_msg_file")"

# Commits generated by git or by the rebase flow are not Conventional Commits
# and are not ours to rewrite.
case "$subject" in
  'Merge '* | 'Revert '* | 'fixup! '* | 'squash! '*) exit 0 ;;
esac

pattern='^(feat|fix|docs|style|refactor|perf|test|build|ci|chore|revert)(\([a-z0-9._-]+\))?!?: .+'

if [[ ! "$subject" =~ $pattern ]]; then
  {
    printf '✗ Commit subject does not follow Conventional Commits:\n\n'
    printf '    %s\n\n' "$subject"
    printf 'Expected: <type>(<scope>): <subject>\n'
    printf 'Types:    feat fix docs style refactor perf test build ci chore revert\n'
    printf 'See CONTRIBUTING.md §Commit conventions.\n'
  } >&2
  exit 1
fi

# CONTRIBUTING.md asks for subjects under 72 characters. Enforced here so the
# rule is checked at the moment it can still be fixed.
if (( ${#subject} > 72 )); then
  {
    printf '✗ Commit subject is %d characters; keep it under 72:\n\n' "${#subject}"
    printf '    %s\n' "$subject"
  } >&2
  exit 1
fi
